head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > groupby]<br/>Body Column 을 기준으로 데이터를 그룹핑하여 Group Header/Footer 함께 표시합니다.",
    "validation" : [
        "options(선택) 파라미터로 GroupBy 기능 실행에 필요한 옵션값을 객체로 설정해야 합니다.",
        "sortIndex(필수) 파라미터로 그룹핑할 Body Column 인덱스를 배열로 설정해야 합니다.",
        "sortIndex(필수) 배열의 원소 갯수가 Group Depth 로 적용되며 groupbyMaxCount 속성값을 초과하여 설정할 수 없습니다.",
        "sortOrder(필수) 파라미터로 그룹핑할 Body Column 의 정렬 방법을 설정해야 합니다.",
        "sortOrder(필수) 에 1 설정 시, 해당 Body Column 을 오름차순으로 정렬합니다.",
        "sortOrder(필수) 에 -1 설정 시, 해당 Body Column 을 내림차순으로 정렬합니다.",
        "sortOrder(필수) 는 sortIndex 파라미터의 배열 원소와 1:1 로 대응되어야 합니다.",
        "hideHeader(선택) 에 true 설정 시, 전체 Group Header 를 화면에 표시하지 않습니다. (groupbyHeader 파라미터는 무시됩니다)",
        "hideHeader(선택) 에 false 설정 시, 전체 Group Header 를 Group Depth 에 맞게 화면에 표시합니다.",
        "hideHeader(선택) 미설정 시, 전체 Group Header 를 Group Depth 에 맞게 화면에 표시합니다. (기본값 false)",
        "hideFooter(선택) 에 true 설정 시, 전체 Group Footer 를 화면에 표시하지 않습니다. (groupbyFooter 파라미터는 무시됩니다)",
        "hideFooter(선택) 에 false 설정 시, 전체 Group Footer 를 Group Depth 에 맞게 화면에 표시합니다.",
        "hideFooter(선택) 미설정 시, 전체 Group Footer 를 Group Depth 에 맞게 화면에 표시합니다. (기본값 false)",
        "groupby() 메소드는 데이터를 기준으로 그룹핑한 후 정렬이 적용되며 별도의 Group Header/Footer 가 제공됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 명시 설정 (초기 selectedIndex 미적용 회피)
    par_sortIndex.setValue("[1]");     // dept 단일 그룹핑
    par_sortOrder.setValue("[1]");     // 오름차순
    par_hideHeader.setValue("1");      // 미설정(코드값 1)
    par_hideFooter.setValue("1");    // 미설정(코드값 1)
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼/데이터 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - 그룹별 행수를 서로 다르게 구성 (부서 개발3/영업2/기획1, 등급 A3/B2/C1, 지역 서울4/부산2) → Group Footer 소계(count) 가 그룹마다 구분됨
    $c.gcm.createLabel('label="[전제] Body Column 0:지역 1:부서 2:등급 3:점수(number), 6행. 그룹별 행수 상이(부서 개발3/영업2/기획1, 등급 A3/B2/C1, 지역 서울4/부산2) → 소계 구분\n[절차] sortIndex/sortOrder/hideHeader/hideFooter 선택 후 [groupby 실행] 클릭\n[확인] 결과창의 데이터Row 그룹순서(그룹핑+정렬) + Group Header(그룹명)/Group Footer(최상위=합계, 하위=소계 + count) 표시여부"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (Body Column id 와 동일한 컬럼 id)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="score" name="score" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 그룹핑 검증용 데이터 : 원본은 그룹이 섞인 순서 → groupby 시 데이터 기준으로 재정렬/그룹핑됨(@spec1)
    //  - 그룹별 행수를 서로 다르게 구성해 Group Footer 소계(count) 가 그룹마다 구분되도록 함
    //    · 부서(1) : 개발 3행 / 영업 2행 / 기획 1행
    //    · 등급(2) : A 3행 / B 2행 / C 1행
    //    · 지역(0) : 서울 4행 / 부산 2행
    let jsonData = [
        { "region": "부산", "dept": "기획", "grade": "C", "score": 60 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 20 },
        { "region": "서울", "dept": "영업", "grade": "B", "score": 40 },
        { "region": "부산", "dept": "영업", "grade": "B", "score": 50 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 10 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 30 }
    ];
    dlt_bind.setJSON(jsonData, false);

    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Body 4컬럼) - 다중 Depth 그룹핑 시 Group Header/Footer Row 까지 모두 렌더되도록 height 넉넉히 지정
    // (최대 케이스: sortIndex=[0,1] 2 Depth → 데이터6 + Header6 + Footer6 = 18 Row, oneRowHeight~38px → 21 Row Slot 확보)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:600px;height:900px;">';
    strTarget += '<w2:caption style="" id="caption1" value="groupby 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol1" value="지역(0)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol2" value="부서(1)"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="hcol3" value="등급(2)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="점수(3)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : region
    strTarget += '<w2:column width="100" style="" inputType="text" id="region" dataList="region"></w2:column>';
    // index 1 : dept
    strTarget += '<w2:column width="100" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    // index 2 : grade
    strTarget += '<w2:column width="80" style="" inputType="text" id="grade" dataList="grade"></w2:column>';
    // index 3 : score (number)
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="score" dataList="score"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// depth 계층 가시화 들여쓰기 : depth×2칸 순수 공백 (depth_0 은 0칸, 깊을수록 2칸씩 누적)
//  결과 출력영역을 left 정렬(<style> 에서 지정)로 고정했으므로 순수 공백 들여쓰기가 그대로 보인다.
scwin._depthMark = function (depth) {
    return "  ".repeat(depth);
};

// groupby 실행 + DOM 실측 검증
//  - sortIndex/sortOrder : 그룹기준 컬럼 + 정렬방향 (배열)
//  - hideHeader/hideFooter : gdl_boolean (미설정='' / 'true' / 'false')
//  - 검증 : 데이터Row 그룹순서(그룹핑+정렬결과) / 첫Row·마지막Row 유형으로 Header·Footer 표시여부 / Header·Footer 내용
scwin.btn_groupby_onclick = function () {
    let si = JSON.parse(par_sortIndex.getValue());
    let so = JSON.parse(par_sortOrder.getValue());
    let options = { sortIndex: si, sortOrder: so };

    // hideHeader / hideFooter : gdl_boolean 라벨로 분기 (미설정 시 옵션 생략 → 기본값 false)
    let hhTxt = par_hideHeader.getText();
    let hfTxt = par_hideFooter.getText();
    let hhApplied = "미설정(생략)";
    let hfApplied = "미설정(생략)";
    if (hhTxt === "true") { options.hideHeader = true; hhApplied = "true"; }
    else if (hhTxt === "false") { options.hideHeader = false; hhApplied = "false"; }
    if (hfTxt === "true") { options.hideFooter = true; hfApplied = "true"; }
    else if (hfTxt === "false") { options.hideFooter = false; hfApplied = "false"; }

    // groupbyHeader / groupbyFooter : 표시되는 Group Header/Footer 에 항상 최소 내용 고정 표시
    //  (빈 Row 대신 내용 표시 - hideHeader/Footer 표시/미표시 대비를 명확히 하기 위한 최소 수단)
    //  - Group Header : 그룹 토글 + 그룹명(toggle()+depthStr())
    //  - Group Footer : depth_0(최상위 그룹)='합계', 하위 depth='소계' 라벨 + 그룹 행수(count())
    //    · groupbyFooter 를 depth별 객체(depth_{n}) 형식으로 구성해 depth 별 라벨을 다르게 표시
    //  ※ hideHeader/hideFooter=true 시에는 각각 무시됨(엔진 처리)
    options.groupbyHeader = [
        { inputType: "expression", expression: "toggle() + depthStr()", colSpan: 4, align: "left" }
    ];
    let footerObj = {};
    for (let d = 0; d < si.length; d++) {
        let label = (d === 0) ? "합계" : "소계"; // depth_0(최상위)=합계, 하위=소계
        footerObj["depth_" + d] = [
            { value: label, colSpan: 3, align: "right" },
            { inputType: "expression", expression: "count()", align: "center" }
        ];
    }
    options.groupbyFooter = footerObj;

    // 이전 그룹핑 상태 초기화 후 재그룹핑
    if (target1.groupbyStatus && target1.groupbyStatus.grouped) {
        target1.clearGroupby();
    }
    target1.groupby(options);

    // DOM 실측 : body tbody 의 각 Row 를 그룹Row(w2grid_groupby) / 데이터Row 로 분류
    let tbody = document.getElementById(target1.id + "_body_tbody");
    let trs = tbody.querySelectorAll("tr");
    let types = [];
    let screenLines = [];   // 화면(tbody)에 렌더된 순서대로 각 Row 의 표시 텍스트
    let groupRowCnt = 0;
    let depthCount = si.length;   // 데이터 행 들여쓰기 기준(그룹 depth 수)
    for (let i = 0; i < trs.length; i++) {
        let tr = trs[i];
        // 데이터보다 많은 Row Slot 은 숨김 filler Row (w2grid_hidedRow, display:none) → 제외
        if (tr.style.display === "none" || tr.className.indexOf("w2grid_hidedRow") >= 0) {
            continue;
        }
        let isGroup = tr.querySelector("td.w2grid_groupby") ? true : false;
        types.push(isGroup ? "G" : "D");
        if (isGroup) groupRowCnt++;
        // 화면 표시 순서 그대로 : 실제 표시되는 셀 텍스트를 컬럼 순서대로 이어붙임
        //  - colSpan 을 누적해 Body 컬럼 수(4)에 도달하면 종료 → colSpan 뒤에 붙는 phantom 빈 td 는 제외
        let cells = [];
        let colAcc = 0;
        let tdList = tr.querySelectorAll("td");
        for (let k = 0; k < tdList.length && colAcc < 4; k++) {
            let td = tdList[k];
            if (td.style.display === "none") continue;
            colAcc += parseInt(td.getAttribute("colSpan") || "1", 10);
            cells.push((td.textContent || "").replace(/ /g, " ").trim());
        }
        // 행 depth 판정 : 그룹 td(w2grid_groupby_depth_N) 있으면 그 N, 없으면 데이터 행 → depthCount
        //  _depthMark(depth) 가시 들여쓰기(표현만, 셀 실측값은 그대로)
        let rowDepth = depthCount;
        let gtd = tr.querySelector("td[class*='w2grid_groupby_depth_']");
        if (gtd) {
            let m = gtd.className.match(/w2grid_groupby_depth_(\d+)/);
            if (m) rowDepth = parseInt(m[1], 10);
        }
        screenLines.push(scwin._depthMark(rowDepth) + cells.join(" | "));
    }
    let firstT = types.length ? types[0] : "-";
    let lastT = types.length ? types[types.length - 1] : "-";
    let headerShown = (firstT === "G") ? "표시" : "숨김";
    let footerShown = (lastT === "G") ? "표시" : "숨김";

    // 출력 : 적용 요약(정렬/hide/그룹Row수) + 그리드 화면에 표시된 순서 그대로의 각 Row 텍스트
    let out = "[적용] sortIndex=" + JSON.stringify(si) + " sortOrder=" + JSON.stringify(so)
        + " hideHeader=" + hhApplied + " hideFooter=" + hfApplied
        + " | Group Header(첫Row)=" + headerShown + " Group Footer(마지막Row)=" + footerShown
        + " | Group Row수=" + groupRowCnt
        + "\n[화면 표시 순서]\n" + (screenLines.length ? screenLines.join("\n") : "(표시 Row 없음)");
    wf_body_bottom.getObj("scwin").setReturnValue(out);
}
